//! Derive compiled-code/ABI/function identities. No RPC or proof approval.
use anyhow::{ensure,Result};use std::{env,fs,io::Write};use plonky2::field::goldilocks_field::GoldilocksField as F;use psy_client_common::data::qhashout::QHashOut;use psy_client_data::config::store_config::PsyHasher;use psy_compiler::output::serialize::CompilationArtifact;use psy_prover::session::gen_contract_deploy_and_circuits_for_functions;use sha2::{Digest,Sha256};
fn main()->Result<()>{let a=env::args().collect::<Vec<_>>();ensure!(a.len()==3,"COMPILED_ARTIFACT FRESH_REPORT");let bytes=fs::read(&a[1])?;let artifact:CompilationArtifact=serde_json::from_slice(&bytes)?;ensure!(artifact.state_tree_height==31,"U124 component identity height");let manifest=psy_data::v1::qdata::contract::canonical_layout_manifest_from_compiler_abi_json::<parth_core::pgoldilocks::PoseidonHasher,F,parth_core::pgoldilocks::QHashOut<F>>(&serde_json::to_string(&artifact.abi)?,psy_core::constants::protocol::STATE_LAYOUT_TREE_HEIGHT,psy_data::v1::qdata::contract::CANONICAL_TYPE_LAYOUT_STRUCT_TREE_HEIGHT)?;let(_,code)=gen_contract_deploy_and_circuits_for_functions::<psy_client_data::config::store_config::C,2>(0,artifact.state_tree_height as u8,&artifact.circuit_definitions)?;let code=code.into_with_whitelist_root::<PsyHasher>()?;let l=&manifest.layout.contract_layout;let report=serde_json::json!({"artifactSha256":format!("{:x}",Sha256::digest(&bytes)),"codeRoot":code.code_root.to_string(),"layoutRoot":l.state_layout_root.to_string(),"functionTreeRoot":code.function_whitelist_root.to_string(),"stateTreeHeight":artifact.state_tree_height,"layoutFieldCount":l.state_layout_field_count,"layoutSlotCount":l.state_layout_slot_count,"scope":"compiled component identity only, not source approval, initial-layout proof or chain inclusion","broadcast":false});let mut out=fs::OpenOptions::new().write(true).create_new(true).open(&a[2])?;out.write_all(&serde_json::to_vec_pretty(&report)?)?;out.sync_all()?;Ok(())}
